This can be replicated without universal by using the below code.

**index.js**
```js
async function loadEsmModule(modulePath) {
  return new Function('modulePath', `return import(modulePath);`)(modulePath);
}

(async ()=> {
  require('zone.js/node');
  await loadEsmModule('@angular/core');
})();
```
